function crc64xz(bytes){
  var P=BigInt('0xC96C5795D7870F42');
  var crc=BigInt('0xFFFFFFFFFFFFFFFF');
  var MASK=BigInt('0xFFFFFFFFFFFFFFFF');
  for(var i=0;i<bytes.length;i++){
    crc^=BigInt(bytes[i]);
    for(var k=0;k<8;k++){
      if((crc&BigInt(1))!==BigInt(0)) crc=((crc>>BigInt(1))^P)&MASK;
      else crc=(crc>>BigInt(1))&MASK;
    }
  }
  crc^=MASK;
  return '0x'+crc.toString(16).toUpperCase().padStart(16,'0');
}
